-- Additive, independent V5 tables. Historical tables are never updated.
CREATE TABLE IF NOT EXISTS v5_releases (release_id TEXT PRIMARY KEY, instrument_version TEXT NOT NULL, instrument_hash TEXT NOT NULL, instrument_json TEXT NOT NULL, manifest_json TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS v5_blocks (block_id TEXT PRIMARY KEY, release_id TEXT NOT NULL REFERENCES v5_releases(release_id), allocation_kind TEXT NOT NULL, sequence_json TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS v5_participants (participant_id TEXT PRIMARY KEY, release_id TEXT NOT NULL REFERENCES v5_releases(release_id), sequence_id TEXT NOT NULL, randomization_block_id TEXT NOT NULL REFERENCES v5_blocks(block_id), block_slot INTEGER NOT NULL CHECK(block_slot BETWEEN 0 AND 3), assigned_at TEXT NOT NULL, is_test INTEGER NOT NULL CHECK(is_test IN (0,1)), is_pilot INTEGER NOT NULL CHECK(is_pilot IN (0,1)), consented_at TEXT NOT NULL, consent_sha256 TEXT NOT NULL, background_json TEXT NOT NULL, option_order_json TEXT NOT NULL, stage TEXT NOT NULL, stage_started_at TEXT NOT NULL, deadline TEXT NOT NULL, status TEXT NOT NULL, completed_at TEXT, final_json TEXT NOT NULL DEFAULT '{}', UNIQUE(randomization_block_id,block_slot));
CREATE TABLE IF NOT EXISTS v5_identities (participant_id TEXT PRIMARY KEY REFERENCES v5_participants(participant_id), name TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS v5_periods (participant_id TEXT NOT NULL REFERENCES v5_participants(participant_id), period INTEGER NOT NULL CHECK(period IN (1,2)), paper_id TEXT NOT NULL, condition TEXT NOT NULL CHECK(condition IN ('self_directed','structured')), instrument_version TEXT NOT NULL, prompt_version TEXT NOT NULL, model_id TEXT NOT NULL, paper_text_version TEXT NOT NULL, paper_text_hash TEXT NOT NULL, logging_coverage TEXT NOT NULL DEFAULT 'unobserved', owner_tab TEXT, last_observed_at TEXT, PRIMARY KEY(participant_id,period), UNIQUE(participant_id,paper_id), UNIQUE(participant_id,condition));
CREATE TABLE IF NOT EXISTS v5_responses (participant_id TEXT NOT NULL REFERENCES v5_participants(participant_id), period INTEGER, item_id TEXT NOT NULL, selected_option_id TEXT NOT NULL, correct INTEGER NOT NULL CHECK(correct IN (0,1)), submitted_at TEXT NOT NULL, stage_elapsed_seconds REAL NOT NULL, PRIMARY KEY(participant_id,item_id), FOREIGN KEY(participant_id,period) REFERENCES v5_periods(participant_id,period));
CREATE TABLE IF NOT EXISTS v5_exchanges (exchange_id TEXT PRIMARY KEY, participant_id TEXT NOT NULL, period INTEGER NOT NULL, required_exchange_number INTEGER NOT NULL CHECK(required_exchange_number BETWEEN 1 AND 5), user_message_id TEXT NOT NULL UNIQUE, assistant_message_id TEXT UNIQUE, structured_stage TEXT, user_text TEXT NOT NULL, assistant_text TEXT, submitted_at TEXT NOT NULL, completed_at TEXT, status TEXT NOT NULL, UNIQUE(participant_id,period,required_exchange_number), FOREIGN KEY(participant_id,period) REFERENCES v5_periods(participant_id,period));
CREATE TABLE IF NOT EXISTS v5_requests (request_id TEXT PRIMARY KEY, exchange_id TEXT NOT NULL REFERENCES v5_exchanges(exchange_id), retry_number INTEGER NOT NULL, started_at TEXT NOT NULL, finished_at TEXT, status TEXT NOT NULL, error_status TEXT, provenance_json TEXT NOT NULL, usage_json TEXT, UNIQUE(exchange_id,retry_number));
CREATE TABLE IF NOT EXISTS v5_predictions (participant_id TEXT NOT NULL, period INTEGER NOT NULL, draft_score INTEGER CHECK(draft_score BETWEEN 0 AND 5), predicted_score INTEGER CHECK(predicted_score BETWEEN 0 AND 5), actual_score INTEGER CHECK(actual_score BETWEEN 0 AND 5), prediction_timestamp TEXT, PRIMARY KEY(participant_id,period), FOREIGN KEY(participant_id,period) REFERENCES v5_periods(participant_id,period));
CREATE TABLE IF NOT EXISTS v5_measures (participant_id TEXT NOT NULL, period INTEGER NOT NULL, item_name TEXT NOT NULL, value INTEGER NOT NULL, response_timestamp TEXT NOT NULL, PRIMARY KEY(participant_id,period,item_name), FOREIGN KEY(participant_id,period) REFERENCES v5_periods(participant_id,period));
CREATE TABLE IF NOT EXISTS v5_consultation_events (event_id TEXT PRIMARY KEY, participant_id TEXT NOT NULL, release_id TEXT NOT NULL, sequence_id TEXT NOT NULL, period INTEGER NOT NULL, paper_id TEXT NOT NULL, condition TEXT NOT NULL, consultation_session_id TEXT NOT NULL, event_type TEXT NOT NULL CHECK(event_type IN ('paper_open','paper_close')), timestamp TEXT NOT NULL, received_at TEXT NOT NULL, timestamp_source TEXT NOT NULL, close_reason TEXT, is_inferred INTEGER NOT NULL CHECK(is_inferred IN (0,1)), client_event_id TEXT NOT NULL UNIQUE, UNIQUE(consultation_session_id,event_type), FOREIGN KEY(participant_id,period) REFERENCES v5_periods(participant_id,period));
CREATE TABLE IF NOT EXISTS v5_transitions (event_id TEXT PRIMARY KEY, participant_id TEXT NOT NULL REFERENCES v5_participants(participant_id), from_stage TEXT NOT NULL, to_stage TEXT NOT NULL, timestamp TEXT NOT NULL, reason TEXT NOT NULL, stage_elapsed_seconds REAL NOT NULL);
